const r = db.users.insertOne({
name: "Ada",
email: "ada@x",
age: 30,
tags: ["math"],
created_at: new Date(),
})
// { acknowledged: true, insertedId: ObjectId("...") }
Auto-generated _id (ObjectId) is returned. Supply your own to override:
db.users.insertOne({ _id: "ada-001", name: "Ada" })

const r = db.users.insertMany([
{ name: "Bob", age: 25 },
{ name: "Cy", age: 41 },
{ name: "Dora", age: 33 },
])
// { acknowledged: true, insertedIds: { 0: ObjectId(...), 1: ObjectId(...), 2: ObjectId(...) } }
By default insertMany is ordered — stops at the first error. Use { ordered: false } to keep going + report all failures together (faster bulk loads):
db.users.insertMany(docs, { ordered: false })

db.users.find({ age: { $gte: 30 } })
find returns a cursor. In mongosh, it auto-iterates and prints. In code, materialise to an array:
const arr = await db.collection('users').find({ age: { $gte: 30 } }).toArray();
Or iterate stream-style for large results:
for await (const doc of cursor) { /* ... */ }

db.users.updateOne(
{ name: "Ada" },
{ $set: { age: 31, "address.city": "Cambridge" } }
)
Dot notation reaches into sub-documents. Missing intermediate fields are auto-created.

db.users.updateOne({ name: "Ada" }, { $push: { tags: "engineer" } })
Push multiple with $each:
db.users.updateOne(
{ name: "Ada" },
{ $push: { tags: { $each: ["engineer", "writer"] } } }
)
Combined with $slice, $sort, $position:
db.users.updateOne(
{ name: "Ada" },
{
$push: {
recent_views: {
$each: ["p3"],
$slice: -10 // keep last 10
}
}
}
)

db.users.updateOne({ name: "Ada" }, { $addToSet: { tags: "engineer" } })
// adds only if "engineer" not already in tags
Use when the array must contain unique values.

Update the first matched element of an array:
db.orders.updateOne(
{ _id: "o1", "items.p": "p1" },
{ $set: { "items.$.qty": 5 } }
)
Update all matched elements ($[]):
db.users.updateMany({}, { $inc: { "scores.$[]": 1 } }) // +1 to every score
Update matched by arrayFilters ($[<id>]):
db.users.updateMany(
{},
{ $set: { "scores.$[low]": 50 } },
{ arrayFilters: [{ "low": { $lt: 50 } }] }
)

Write an update that decrements products.stock by 1 for p1 only if stock > 0 (so it never goes negative).
Solution
db.products.updateOne(
{ _id: "p1", stock: { $gt: 0 } },
{ $inc: { stock: -1 } }
)
// matchedCount = 0 means stock was already 0; handle in app code

What · How
Insert one · db.c.insertOne(doc)
Insert many · db.c.insertMany([docs], { ordered: false })
Find first · db.c.findOne(filter)
Find all · db.c.find(filter).toArray()
Project · find(filter, { name: 1, _id: 0 })
Sort / limit / skip · .sort({ field: -1 }).limit(N).skip(M)
Cursor stream · for await (const d of cursor)
Set fields · { $set: { f: v } }
Remove field · { $unset: { f: "" } }
Increment · { $inc: { n: 1 } }
Append array · { $push: { arr: x } } or { $each: [...] }
Append unique · { $addToSet: { arr: x } }
Remove array elements · { $pull: { arr: x } }
Pop first/last · { $pop: { arr: -1 } } / { arr: 1 }
Update positional · "arr.$" after match condition
Update by filter · $[<id>] + arrayFilters
Upsert · third arg { upsert: true }
Replace entire doc · replaceOne
Atomic return · findOneAndUpdate({}, {}, { returnDocument: 'after' })
Soft delete · $set: { deleted_at: new Date() }
Bulk · bulkWrite([ops], { ordered: false })
Write concern · { w: "majority", j: true, wtimeout: 5000 }
